import {$,api,post,message,button} from './common.js?v=6.17.0';
let page=0,busy=false;
async function activities(reset=false){if(busy)return;busy=true;$('moreActivities').disabled=true;$('activityKind').disabled=true;try{if(reset){page=0;$('activities').replaceChildren();}const data=await api(`/api/strava/activities?page=${page+1}&kind=${$('activityKind').value}`);page=data.page;for(const a of data.activities){const row=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('small'),link=document.createElement('a');row.className='strava-activity';title.textContent=a.name;meta.textContent=`${new Date(a.startDate).toLocaleDateString('fr')} · ${(a.distance/1000).toFixed(1)} km · ${a.sportType}`;link.href='https://www.strava.com/activities/'+a.id;link.textContent='Voir sur Strava';link.target='_blank';link.rel='noopener noreferrer';const load=button('Choisir cette sortie',async()=>{load.disabled=true;try{const ride=await post('/api/strava/import',{activityId:a.id});location.assign('/?ride='+encodeURIComponent(ride.id));}finally{load.disabled=false;}});row.append(title,meta,link,load);$('activities').append(row);}$('moreActivities').hidden=!data.hasMore;message(data.activities.length?'':data.hasMore?'Aucune sortie de ce type sur cette page. Cherchez dans les sorties plus anciennes.':'Aucune autre sortie de ce type.');}catch(e){message(e.message);}finally{busy=false;$('moreActivities').disabled=false;$('activityKind').disabled=false;}}
async function status(){const s=await api('/api/strava/status');$('stravaStatus').textContent=!s.configured?'La connexion Strava n’est pas encore activée par l’administrateur.':s.connected?'Votre compte Strava est connecté.':'Connectez votre compte pour choisir une sortie gravel.';$('connectStrava').hidden=!s.configured||s.connected;$('disconnectStrava').hidden=!s.connected;$('stravaPicker').hidden=!s.connected||!s.configured;if(s.connected&&s.configured)await activities(true);}
$('moreActivities').onclick=()=>activities();$('activityKind').onchange=()=>activities(true);
$('disconnectStrava').onclick=async()=>{if(!confirm('Déconnecter Strava et supprimer les sorties importées via son API ainsi que leurs secteurs ? Vos autres GPX et secteurs sont conservés.'))return;try{const result=await post('/api/strava/disconnect',{});await status();message(result.remoteRevoked?'Strava déconnecté, imports supprimés.':'Imports supprimés de Sillage. Vérifiez aussi les autorisations de Sillage dans les paramètres Strava.');}catch(e){message(e.message);}};
try{await status();}catch(e){message(e.message);}
